import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  // ----- Helpers -----
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  // ----- Create root group -----
  const root = new Group();

  // Apply placement from config
  if (config.position) root.position.set(...config.position);
  if (config.rotation) root.rotation.set(...config.rotation);
  if (config.scale) root.scale.set(...config.scale);

  // ----- Determine plane size based on atlas region (fallback to 1:1) -----
  // Atlas region info (hard‑coded for this spec)
  const region = { x: 0, y: 0, width: 512, height: 320 };
  const aspect = region.width / region.height; // 1.6

  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // ----- Create node material -----
  const material = new MeshBasicNodeMaterial();
  material.color = new Color(0xffffff);

  // Placeholder texture node (will be filled once the texture loads)
  let texNode = texture(null, uv());

  // Apply UV offset/scale for the atlas region (assumes full atlas size equals region size)
  // If the atlas is larger, replace these values with the correct normalized values.
  const uvScale = vec2(region.width / region.width, region.height / region.height); // (1,1)
  const uvOffset = vec2(region.x / region.width, region.y / region.height); // (0,0)
  const transformedUV = add(mul(uv(), uvScale), uvOffset);
  texNode = texture(null, transformedUV);
  material.mapNode = texNode;

  // ----- Load texture asynchronously -----
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      // Update the texture node with the loaded texture
      texNode.value = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      // Fail silently – keep material white
    });

  // ----- Assemble mesh -----
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // ----- Event handlers placeholder -----
  root.userData.handlers = {};

  // ----- Cleanup routine -----
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose loaded texture if it arrived
    if (texNode?.value && texNode.value.dispose) {
      texNode.value.dispose();
    }

    // Kill any GSAP timelines (none in this node but defensive)
    gsap.globalTimeline.clear();
  };

  // Return the node
  return root;
}
